export const agentSettingGroups = ['model-provider', 'runtime', 'tools-skills', 'mcp', 'scheduler', 'channels', 'permissions', 'diagnostics'];

export function renderAgentSettingsPage({ configEndpoint = '/api/config', statusEndpoint = '/api/status' } = {}) {
  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Agent 底座设置</title><style>body{font-family:system-ui;max-width:860px;margin:32px auto;padding:0 20px;background:#f5f8f4;color:#243b2f}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}.card{background:#fff;border:1px solid #dce8dc;border-radius:10px;padding:16px}label{display:block;margin:9px 0 4px}input,select{width:100%;box-sizing:border-box;padding:8px;border:1px solid #ccd8cc;border-radius:5px}button{margin-top:12px;padding:8px 14px;border:0;border-radius:5px;background:#2f855a;color:#fff}pre{white-space:pre-wrap;background:#f1f5f1;padding:10px}</style><h1>Agent 底座设置</h1><p>所有产品共用的运行时设置</p><div class="grid"><section class="card"><h2>模型 Provider</h2><label>API Key<input id="key" type="password"></label><label>Provider 地址<input id="url"></label><label>默认模型<input id="model"></label></section><section class="card"><h2>Agent Runtime</h2><label>Runtime<select id="runtime"><option>agent-platform</option><option>legacy</option></select></label><label>确认策略<select id="confirm"><option>写操作需要确认</option><option>全部自动执行</option></select></label></section><section class="card"><h2>Tool / Skill</h2><label><input type="checkbox" checked> 启用产品工具</label><label><input type="checkbox" checked> 启用 Agent Skills</label><label><input type="checkbox"> 启用 MCP 工具</label></section><section class="card"><h2>MCP 配置</h2><label>允许的 MCP Server<input placeholder="逗号分隔"></label><label>最小权限 Scope<input placeholder="read,write"></label></section><section class="card"><h2>Scheduler</h2><label><input type="checkbox"> 启用定时运行</label><label>默认时区<input value="Asia/Shanghai"></label></section><section class="card"><h2>Channels</h2><p id="channel">加载中…</p><p>当前账号与连接状态由底座统一管理。</p></section><section class="card"><h2>权限与确认</h2><p>高风险写入、外发消息和库存操作默认需要发起人确认。</p></section><section class="card"><h2>运行日志与诊断</h2><pre id="diag">加载中…</pre></section></div><button onclick="save()">保存模型设置</button> <span id="msg"></span><script>async function load(){const c=await(await fetch('${configEndpoint}')).json();model.value=c.model||'';url.value=c.baseUrl||'';const s=await(await fetch('${statusEndpoint}')).json();channel.textContent=JSON.stringify(s.connector);diag.textContent=JSON.stringify(s,null,2)}async function save(){const r=await fetch('${configEndpoint}',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({apiKey:key.value,model:model.value,baseUrl:url.value})});msg.textContent=r.ok?'已保存':'保存失败'}load()</script></html>`;
}
